// دالة فحص تصريح المشرف الآمن للواجهات البرمجية
async function verifyAdminRequest(req: express.Request): Promise<{ authorized: boolean; reason?: string; userEmail?: string }> {
  const adminApiKey = await getOrInitAdminApiKey();
  
  // 1. التحقق عبر ترويسة المفتاح المباشر x-admin-key أو x-import-api-key
  const headerKey = (req.headers['x-admin-key'] as string) || (req.headers['x-import-api-key'] as string);
  if (headerKey && (headerKey === adminApiKey || (process.env.IMPORT_API_KEY && headerKey === process.env.IMPORT_API_KEY))) {
    return { authorized: true, userEmail: ADMIN_EMAIL };
  }

  // 2. التحقق عبر ترويسة Authorization
  const authHeader = req.headers['authorization'];
  if (authHeader && authHeader.startsWith('Bearer ')) {
    const token = authHeader.substring(7).trim();
    if (token === adminApiKey || (process.env.IMPORT_API_KEY && token === process.env.IMPORT_API_KEY)) {
      return { authorized: true, userEmail: ADMIN_EMAIL };
    }

    // فحص ما إذا كان الرمز هو Firebase ID Token صالحاً لمشرفة النظام
    if (firebaseConfig.apiKey) {
      try {
        const verifyUrl = `https://identitytoolkit.googleapis.com/v1/accounts:lookup?key=${firebaseConfig.apiKey}`;
        const lookupRes = await new Promise<{ ok: boolean; data: any }>((resolve) => {
          const postData = JSON.stringify({ idToken: token });
          const request = https.request(verifyUrl, {
            method: 'POST',
            headers: {
              'Content-Type': 'application/json',
              'Content-Length': Buffer.byteLength(postData)
            }
          }, (res) => {
            let data = '';
            res.on('data', chunk => data += chunk);
            res.on('end', () => {
              try {
                resolve({ ok: res.statusCode === 200, data: JSON.parse(data) });
              } catch {
                resolve({ ok: false, data: null });
              }
            });
          });
          request.on('error', () => resolve({ ok: false, data: null }));
          request.write(postData);
          request.end();
        });

        if (lookupRes.ok && lookupRes.data?.users?.[0]) {
          const userObj = lookupRes.data.users[0];
          const email = (userObj.email || '').toLowerCase();
          const uid = userObj.localId;

          if (email === ADMIN_EMAIL.toLowerCase()) {
            return { authorized: true, userEmail: email };
          }

          // فحص الصلاحية في كوليكشن users في Firestore
          const db = getDb();
          const userDoc = await getDoc(doc(db, 'users', uid));
          if (userDoc.exists() && userDoc.data()?.role === 'admin') {
            return { authorized: true, userEmail: email };
          }
        }
      } catch (tokenErr) {
        console.warn("Token verification error:", tokenErr);
      }
    }
  }

  return { 
    authorized: false, 
    reason: 'غير مصرح: يرجى تقديم مفتاح المشرف الصالح في الترويسة (x-admin-key) أو رمز اعتماد المشرف (Bearer Token).' 
  };
}

